// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount <= address(this).balance); // ensure enough ETH
        vm.deal(sender, amount);

        // Deposit so sender has credit
        vm.prank(sender);
        c.deposit{value: amount}();

        // Now withdraw all; should succeed if credit > 0, otherwise should revert in reference but not in mutant
        vm.prank(sender);
        // We need to check behavior when credit is zero. After deposit, credit is amount.
        // To test zero credit case, we would need a different flow, but the rule is:
        // After deposit, withdrawAll never reverts.
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(success);
    }
}

